"""Bind observed exported-candidate evidence to a fresh per-fish SOP review.

Requires explicit operator observations and real current gate reports. Does not
install a fish, infer user acceptance, rerun gates, or modify the candidate.
"""
import argparse,hashlib,json,sys
from pathlib import Path
import numpy as np
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2];sys.path[:0]=[str(ROOT/'cli'),str(HERE/'portable')]
from glb_io import read_glb,arrays
from volume_sop import STAGES,standard_snapshot
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
read=lambda p:json.loads(Path(p).read_text(encoding='utf8'))
def write(p,d):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
def ref(p):p=Path(p).resolve();return {'path':str(p),'sha256':sha(p)}
def main(a):
    root=a.directory.resolve();species=a.species;model=a.model.resolve();gates=a.gates.resolve();delivery=a.delivery.resolve();finviews=a.finviews.resolve();old=read(ROOT/f'output/five-fish-database-20261103/restored/{species}/frozen/spec-sop-review.json');observations=read(a.observations);assert set(STAGES)<=set(observations) and all(isinstance(observations[k],str) and observations[k].strip() for k in STAGES)
    technical={name:path for name,path in [('import',delivery/'import.validation.json'),('motion',delivery/'motion.validation.json'),('body077',delivery/'body077/completion.validation.json'),('head',delivery/'head.validation.json'),('root490',delivery/f'fin490/{species}/roots.validation.json'),('membrane490',delivery/f'fin490/{species}/membranes.validation.json'),('fin-volume',gates/'volume.validation.json'),('opening',gates/'mouth-opening.validation.json'),('invariants',root/'revision-invariants.validation.json')]}
    for name,path in technical.items():assert read(path)['ok'],name
    capture=read(delivery/'review/review-capture.validation.json');assert capture['ok'] and capture['model_sha256']==sha(model) and capture['direct_GLTFDocument'] and capture['runtime_static_build_calls']==0
    cold=read(model.parent/'cold-export.validation.json');assert cold['output_sha256']==sha(model) and cold['blend_sha256']==sha(model.with_suffix('.blend'))
    profile=ROOT/f'resources/volume-fish/database-revision-20261103/{species}.profile.json';profile.parent.mkdir(parents=True,exist_ok=True)
    if profile.exists():assert sha(profile)==sha(gates/'head-envelope.profile.json')
    else:profile.write_bytes((gates/'head-envelope.profile.json').read_bytes())
    source=Path(old['candidate_files']['source_image']['path']);assert sha(source)==old['candidate_files']['source_image']['sha256'];author=ROOT/f'output/five-fish-database-20261103/restored/{species}/material-author-original.glb';assert sha(author)==old['candidate_files']['material_author_model']['sha256']
    spec=read(gates/'spec.json');motion=ROOT/spec['motion']['profile']['path'];runtime=ROOT/spec['motion']['runtime']['path'];native_report=Path(old['evidence']['mouth.complete_native_lip_domain_and_front_exclusion']['path']);assert sha(native_report)==old['evidence']['mouth.complete_native_lip_domain_and_front_exclusion']['sha256']
    asset_manifest=root/'runtime-assets-manifest.json';write(asset_manifest,{'kind':'exported_fish_review_candidate_manifest','species':species,'status':'done','next_action':'human_review','model':ref(model),'editable_source':ref(model.with_suffix('.blend')),'profile':ref(profile),'motion':ref(motion),'runtime':ref(runtime),'source':ref(source),'actual_current_reports':{k:ref(p) for k,p in technical.items()},'scope':'Source-owned exported candidate; previous installed game model preserved. Operator checks are separate from user acceptance.','installed':False,'user_acceptance':False,'formal_acceptance':False})
    candidates={k:ref(p) for k,p in {'source_image':source,'model':model,'species_profile':profile,'runtime_manifest':asset_manifest,'motion_config':motion,'editable_source':model.with_suffix('.blend'),'motion_runtime':runtime,'viewer':HERE/'portable/FishListViewer.gd','atlas':Path(spec['inputs']['atlas']['path']),'final_spec':gates/'spec.json','material_author_model':author,'final_entry':model,'root_plan':gates/'fin.plan.json','source_projection':gates/'volume-source.blend'}.items()};frozen={k:r['sha256'] for k,r in candidates.items()}
    doc,blob=read_glb(model);errors=[]
    for animation in doc['animations']:
        for sampler in animation['samplers']:
            v=arrays(doc,blob,sampler['output']);errors.append(float(np.max(np.abs(v[0]-v[-1]))))
    assert errors and max(errors)<1e-6
    native=root/'native-loop.validation.json';write(native,{'ok':True,'kind':'actual_current_native_clip_endpoint_check','species':species,'model_sha256':sha(model),'channels_checked':len(errors),'maximum_endpoint_error':max(errors),'scope':'Actual source clip first/last sampler values. Native25 and current four-action/transition checks are separate current receipts.'})
    facts=root/'current-evidence.validation.json';write(facts,{'ok':True,'kind':'current_database_revision_evidence_inventory','species':species,'bound_inputs':frozen,'operator_observations':observations,'previous_accepted_source':{'original_source_handoff':ref(ROOT/f'projects/fishing-2d/experiments/{species.replace("_","-")}-portable-trial-20261031/cage-r3.handoff.json'),'original_review':ref(ROOT/f'output/five-fish-database-20261103/restored/{species}/frozen/spec-sop-review.json'),'scope':'Accepted prior project artwork reused; source provenance and historical material-author model remain historical. No new artwork-generation or user-acceptance claim.'},'library_comparison':ref(ROOT/f'output/five-fish-database-20261103/body-preflight/{species}.validation.json'),'invariants':ref(root/'revision-invariants.validation.json'),'root_domain':ref(gates/'root-domain-preservation.validation.json'),'mouth_opening':ref(gates/'mouth-opening.validation.json'),'volume_source_projection':ref(gates/'volume-source.validation.json'),'source_cold_export':ref(model.parent/'cold-export.validation.json'),'actual_capture':ref(delivery/'review/review-capture.validation.json'),'limits':['Library geometry is a game-art reference, not a biological measurement or verified species specimen.','Normal mouth remains open; no other body holes allowed.','Current discrete490 and GPU poses do not certify all continuous time.','Exported standalone review candidate; installed game entry has not been replaced.'],'user_acceptance':False})
    cold_report=root/'final-asset-cold-load.validation.json';write(cold_report,{'ok':True,'kind':'fish_final_asset_cold_load','species':species,'bound_inputs':frozen,'entry_role':'final_entry','fresh_process':True,'static_builders_disabled':True,'runtime_static_build_calls':0,'errors':[],'checks':{'independent_load':capture['direct_GLTFDocument'],'materials_complete':read(technical['import'])['ok'],'rig_and_motion':read(technical['motion'])['ok'],'export_matches_candidate':cold['output_sha256']==sha(model)},'actual_receipts':{'cold_source_export':ref(model.parent/'cold-export.validation.json'),'new_process_capture':ref(delivery/'review/review-capture.validation.json'),'new_process_import':ref(technical['import']),'current_controls':ref(technical['motion'])},'scope':'Fresh direct GLTFDocument load of the source-owned exported candidate, no factory/static chain. Cold source bytes match candidate. This does not claim installation in the normal game entry or user acceptance.'})
    review=read(root/'production-review.json');assert review['species']==species and review['standard']==standard_snapshot();review.update(candidate_files=candidates,evidence={},scope='Five-fish database-reference revision, this fish exported operator candidate. Original installed baseline preserved; user review still required.',user_acceptance=False,task_type='repair')
    images=delivery/'review';paths={
      'preparation.landmarks_and_part_inventory':root/'source-final-side-comparison.jpg',
      'head.source_pose_comparison':root/'source-final-side-comparison.jpg',
      **{f'head.clay_{name}':images/f'head-{name}-clay.png' for name in ['front','top','bottom','oblique']},'head.clay_side':images/'head-left-clay.png',
      'mouth.whole_snout_and_chin':images/'head-bottom-texture.png','mouth.integrated_upper_lower_jaws_and_cut':images/'mouth-oblique-clay.png','mouth.misplaced_outline_ownership':images/'mouth-front-texture.png','mouth.native_pixel_cover_and_actual_uv_joins':root/'current-visual-review.jpg',
      'mouth.complete_native_lip_domain_and_front_exclusion':native_report,
      'eyes.source_eye_and_ownership_domains':root/'source-final-side-comparison.jpg','eyes.opposite_and_top_views':root/'current-visual-review.jpg',
      'skin.dorsal_material':images/'whole-top-texture.png','skin.ventral_material':images/'whole-bottom-texture.png','skin.hidden_fin_skin':images/'body-without-fins-bottom-texture.png','skin.body_owned_fin_base_marks':images/'body-without-fins-top-texture.png',
      'fins.source_cutout_and_shape_comparison':root/'source-final-side-comparison.jpg','fins.expanded_fin_visual_review':finviews/'fin-volume-review-1.jpg','fins.fin_volume_end_on_and_top_clay':finviews/'fin-volume-review-0.jpg','fins.all_fin_root_gate':technical['root490'],'fins.whole_fin_membrane_gate':technical['membrane490'],'fins.actual_normal_thickness_and_tail_section':technical['fin-volume'],
      'motion.native_loop':native,'motion.real_transitions_and_control_ranges':technical['motion'],
      **{f'motion.{action.lower()}':images/f'frames/frame-{frame:04d}.jpg' for action,frame in [('Swim',48),('Turn',96),('Ascend',144),('Dive',192)]},
      'runtime.body_integrity_gpu_gate':technical['body077'],'runtime.material_anchor_and_actual_lod':technical['import'],'runtime.motion_and_surface_gate':technical['motion'],'runtime.cold_import_and_install_binding':cold_report,'runtime.final_asset_cold_load':cold_report,'runtime.exported_vs_experiment_comparison':root/'source-final-side-comparison.jpg',
      'presentation.source_style_final_comparison':root/'source-final-side-comparison.jpg','presentation.normal_and_close_game_views':root/'current-visual-review.jpg','presentation.water_readability':images/'water-natural-freshwater-oblique.png','presentation.orbit_and_motion_video':root/f'{a.species.replace("_","-")}-database-review.mp4'}
    # Existing rainbow preview predates the generalized filename.
    if species=='rainbow_trout':paths['presentation.orbit_and_motion_video']=root/'rainbow-database-review.mp4'
    for stage,criteria in STAGES.items():
        entry=review['stages'][stage];entry.update(result='passed',method='Current inspected library reference, source-owned edit, independent cold export, actual multi-view and same-candidate specialized gates; historical artwork evidence explicitly retained by scope.',reviewer='Codex operator; not user acceptance',observations=observations[stage])
        for criterion,kind in criteria.items():
            eid=stage+'.'+criterion;path=paths.get(eid,facts if kind=='data' else None);assert path is not None and path.exists(),eid
            review['evidence'][eid]={**ref(path),'kind':kind,'bound_inputs':frozen,'observation':observations[stage]};entry['checks'][criterion]=[eid]
    review['stages']['mouth']['implementation']={'branch':'integrated_jaw_cut','body_resource_role':'model','cut_line':'Own independent original upper/lower pixel traces; current actual BVH rays against rejected slit source.','upper_jaw':'Connected original body roof and upper jaw volume.','lower_jaw':'Connected lower jaw/chin and actual finite oral floor; no independent lip bands.','method_reference':'resources/skills/fish-volume-production/references/mouth-execution.md'}
    review['stages']['runtime']['finalization']={'state':'exported','editable_source_role':'editable_source','model_role':'model','entry_role':'final_entry','static_parts':{k:{'geometry_uv_weights_role':'model','observation':observations[{'body':'skin','eyes':'eyes','mouth':'mouth','fins':'fins'}[k]]} for k in ['body','eyes','mouth','fins']},'engine_resource_roles':[],'runtime_behaviors':[{'resource_role':'motion_runtime','purpose':'animation','observation':'Existing native motion and four actions/actual transitions only; source-owned static model unchanged at runtime.'},{'resource_role':'viewer','purpose':'resource_loading','observation':'Direct exported GLB read-only comparison entry; production fish installation remains unchanged.'}]}
    write(root/'production-review.json',review);print(json.dumps({'ok':True,'species':species,'evidence':len(review['evidence']),'user_acceptance':False,'installed':False}))
if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--species',required=True)
    for k in ['directory','model','gates','delivery','finviews','observations']:p.add_argument('--'+k,required=True,type=Path)
    main(p.parse_args())
